mapper.update:
WITH upsert AS (
    UPDATE scm11_dev_step
       SET scm11_dev_id       = #{devId}
         , scm11_dev_step_seq = #{devStepSeq}
         , scm11_dev_step_cd  = #{devStepCode}
         , scm11_person_id    = #{personId}
     WHERE scm11_dev_step_id  = #{devStepId}
     RETURNING *
)
INSERT INTO scm11_dev_step (scm11_dev_step_id, scm11_dev_id, scm11_dev_step_seq, scm11_dev_step_cd, scm11_person_id)
SELECT f_create_seq(), #{devId}, #{devStepSeq}, #{devStepCode}, #{personId}
 WHERE NOT EXISTS ( SELECT * FROM upsert )

UPDATE scm11_dev_step
   SET scm11_result = #{result}
 WHERE scm11_dev_step_id = #{devStepId}

UPDATE scm11_dev_step
   SET scm11_note   = #{note}
     , scm11_result = #{result}
 WHERE scm11_dev_step_id = #{devStepId}

UPDATE scm11_dev_step SET scm11_dev_status_cd = #{devStatusCd}
, scm11_result_cd = '1' , scm11_result_date = f_sysdate()
, scm11_result_cd = NULL , scm11_result_date = NULL
WHERE scm11_dev_step_id = #{devStepId}

